// Build (Git Bash, project root): export ZIG_GLOBAL_CACHE_DIR=$PWD/host/.zig-cache/global ZIG_LOCAL_CACHE_DIR=$PWD/host/.zig-cache/local; zig c++ -target x86_64-windows-gnu -std=c++17 -O2 -Wall -Wextra -Ifirmware/main -Ihost host/tests/test_kits.cpp firmware/main/core/kits.cpp -x c++ firmware/main/core/kits_808.c firmware/main/core/kits_909.c -o host/bin/test_kits.exe && host/bin/test_kits.exe
//
// Built-in "808 STYLE" / "909 STYLE" kits (core/kits.h, generated by tools/kitgen):
// table layout, guard frames, levels, DC, pitch, spectra and decay times against the circuit
// recipes in docs/BADANIA_SUROWE_WNIOSKI.txt. Also checks that sdcard/ORBIT/KITS/*/ matches.
// Usage: test_kits.exe [project root]   (default ".")
#include <math.h>
#include <stdio.h>
#include <string.h>

#include <complex>
#include <initializer_list>
#include <string>
#include <vector>

#include "core/kits.h"
